use std::ffi::CStr;

fn main() {
    // openssl-sys: linked against the system libcrypto found by pkg-config.
    let v = unsafe { CStr::from_ptr(openssl_sys::OpenSSL_version(openssl_sys::OPENSSL_VERSION)) };
    println!("openssl: {}", v.to_str().unwrap());

    // ring: C and assembly compiled by cc-rs.
    let d = ring::digest::digest(&ring::digest::SHA256, b"breakbulk");
    println!("ring sha256: {:02x?}", &d.as_ref()[..4]);

    // zstd-sys: bindings generated by bindgen at build time.
    let zv = unsafe { CStr::from_ptr(zstd_sys::ZSTD_versionString()) };
    println!("zstd: {}", zv.to_str().unwrap());
}
